def solve(inputs: dict) -> float:
    terms = inputs['terms']

    # Initialize the recurrence relation for numerators
    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0

    if len(terms) == 1:
        return float(p_prev1)

    # Compute p_i for i = 1, 2, ..., n-1
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

